-- 0005_admin_user.sql
-- Grants admin access to one auth user.
--
-- This is the only step that cannot be scripted ahead of time, because the
-- user has to exist first and its id is generated by Supabase.
--
-- 1. Supabase Dashboard -> Authentication -> Users -> "Add user"
--    -> "Create new user". Use a real address and a strong password, and
--    tick "Auto Confirm User" so there is no email round-trip.
-- 2. Copy the new user's UID from that same screen.
-- 3. Paste it below, replacing the placeholder, and run this file.
--
-- There is deliberately no RLS write policy on `public.admins` (see
-- 0002_rls.sql), so this is the ONLY way to create an administrator. A
-- signed-in admin cannot promote anyone else from the browser, and neither
-- can anything that gets hold of the publishable key.
--
-- Safe to run more than once.

insert into public.admins (user_id)
values ('00000000-0000-0000-0000-000000000000')  -- <- replace with the real UID
on conflict (user_id) do nothing;

-- Verification: should return exactly one row, with the address you created.
-- If it returns nothing, the UID above is wrong.
select a.user_id, u.email, a.created_at
from public.admins a
join auth.users u on u.id = a.user_id;
